+    for revocation_nonce in [None, Some(nonce(3))] {
+        roundtrip!(
+            CommitmentSignedV2 {
+                channel_id: [11; 32].into(),
+                commitment_number: u64::MAX - 1,
+                funding_tx_partial_signature: signature(),
+                funding_nonce: nonce(2),
+                revocation_nonce,
+            },
+            commitment_signed_v2,
+            CommitmentSignedV2,
+            21
+        );
+    }
+}
