+    })
+    .to_molecule_bytes();
+    assert_eq!(u32::from_le_bytes(bytes[..4].try_into().unwrap()), 16);
+    let FiberMessage::ChannelNormalOperation(FiberChannelMessage::ClosingSigned(actual)) =
+        FiberMessage::from_molecule_slice(&bytes).unwrap()
+    else {
